[DataContractAttribute]
class SKLSalesOrderReportContract
{
    private FromDate fromDate;
    private ToDate   toDate;
    SalesType       salesType;

}

Method.Source:
[DataMemberAttribute("FromDate"),
SysOperationLabelAttribute("From Date")]
public FromDate parmFromDate(FromDate _fromDate = fromDate)
{
    fromDate = _fromDate;
    return fromDate;
}

[DataMemberAttribute("ToDate"),
SysOperationLabelAttribute("To Date")]
public ToDate parmToDate(ToDate _toDate = toDate)
{
    toDate = _toDate;
    return toDate;
}

[DataMemberAttribute('SalesType'),
SysOperationLabelAttribute('Order Type'),
SysOperationHelpTextAttribute('Select specific sales order type.')]
public SalesType parmSalesType(SalesType _salesType = salesType)
{
    salesType = _salesType;
    return salesType;
}
